'use strict';
(()=>{
  const site=new URLSearchParams(location.search).get('site'),form=document.getElementById('publicEnquiryForm'),notice=document.getElementById('enquiryNotice'),error=document.getElementById('enquiryError');
  let info,submissionId=crypto.randomUUID(),context={pageURL:'',referrer:'',campaign:''};
  window.addEventListener('message',event=>{if(info&&event.source===parent&&event.origin===info.websiteOrigin&&event.data?.type==='profitplus-context'&&event.data.site===site){context={pageURL:String(event.data.pageURL||''),referrer:String(event.data.referrer||''),campaign:String(event.data.campaign||'')};}});
  if(!/^[\w-]{8,100}$/.test(site||'')){notice.textContent='This enquiry form is unavailable.';return;}
  fetch('/api/capture/'+encodeURIComponent(site)+'/info',{credentials:'omit'}).then(async response=>{if(!response.ok)throw Error();info=await response.json();document.getElementById('enquiryBusiness').textContent=info.name;notice.textContent='Send your enquiry directly to '+info.name+'.';form.hidden=false;if(parent!==window)parent.postMessage({type:'profitplus-form-ready',site},info.websiteOrigin);}).catch(()=>{notice.textContent='This enquiry form is unavailable. Please contact the business through another channel.';});
  form.onsubmit=async event=>{event.preventDefault();error.hidden=true;const values=Object.fromEntries(new FormData(form)),button=form.querySelector('button[type=submit]');if(!values.email&&!values.phone){error.textContent='Enter your email or phone number so the business can respond.';error.hidden=false;return;}button.disabled=true;try{const response=await fetch('/api/capture/'+encodeURIComponent(site)+'/enquiry',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,...context,nonce:info.nonce,submissionId})});const data=await response.json();if(!response.ok)throw Error(data.error||'Your enquiry could not be sent.');form.reset();form.hidden=true;notice.textContent='Thank you. Your enquiry has been collected and the business can follow up using your contact details.';}catch(e){error.textContent=e.message;error.hidden=false;}finally{button.disabled=false;}};
})();
